package com.movieticket.movie;
import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest; import static org.assertj.core.api.Assertions.assertThat;
@DataJpaTest class MovieRepositoryIntegrationTest {@Autowired MovieRepository repository; @Test void persistsAndUpdatesMovie(){Movie m=new Movie();m.setTitle("Arrival");m.setGenre("Sci-Fi");m.setDurationMinutes(116);m.setLanguage("English");Movie saved=repository.saveAndFlush(m);assertThat(repository.findById(saved.getId())).isPresent();saved.setTitle("Arrival Updated");repository.saveAndFlush(saved);assertThat(repository.findById(saved.getId()).orElseThrow().getTitle()).isEqualTo("Arrival Updated");repository.delete(saved);assertThat(repository.findById(saved.getId())).isEmpty();}}
